        private void LeaderboardForm_Paint(object sender, PaintEventArgs e) { if (ClientSize.Width <= 1 || ClientSize.Height <= 1) return; Graphics g = e.Graphics; g.SmoothingMode = SmoothingMode.AntiAlias; using (LinearGradientBrush background = new LinearGradientBrush(ClientRectangle, backgroundColor, backgroundSecondary, 45F)) { g.FillRectangle(background, ClientRectangle); } int offset = animationPhase % 42; using (Pen gridPen = new Pen(Color.FromArgb(9, 65, 90, 120), 1)) { for (int x = 0; x < ClientSize.Width; x += 42) { g.DrawLine(gridPen, x, 118 + offset, x, ClientSize.Height); } for (int y = 118; y < ClientSize.Height; y += 42) { g.DrawLine(gridPen, 0, y + offset, ClientSize.Width, y + offset); } } using (SolidBrush glow = new SolidBrush(Color.FromArgb(15, accentColor.R, accentColor.G, accentColor.B))) { g.FillEllipse(glow, ClientSize.Width / 2 - 380, -230, 760, 400); } using (Pen topLine = new Pen(Color.FromArgb(75 + Math.Min(pulseValue, 35), accentColor.R, accentColor.G, accentColor.B), 1.5F)) { g.DrawLine(topLine, 42, 117, ClientSize.Width - 42, 117); } int panelLeft = 35; int panelTop = 128; int panelWidth = ClientSize.Width - 70; int panelHeight = ClientSize.Height - 235; if (panelHeight < 380) panelHeight = 380; using (SolidBrush panelBrush = new SolidBrush(Color.FromArgb(232, panelColor.R, panelColor.G, panelColor.B))) { g.FillRectangle(panelBrush, panelLeft, panelTop, panelWidth, panelHeight); } using (Pen panelPen = new Pen(borderColor, 1)) { g.DrawRectangle(panelPen, panelLeft, panelTop, panelWidth - 1, panelHeight - 1); } using (Pen sectionLine = new Pen(Color.FromArgb(45, accentColor.R, accentColor.G, accentColor.B), 1)) { g.DrawLine(sectionLine, panelLeft + 12, panelTop + 43, ClientSize.Width - panelLeft - 12, panelTop + 43); } using (Pen bottomLine = new Pen(Color.FromArgb(55, 65, 155, 255), 1)) { g.DrawLine(bottomLine, 42, ClientSize.Height - 67, ClientSize.Width - 42, ClientSize.Height - 67); } }
        private void AnimationTimer_Tick(object sender, EventArgs e) { animationPhase++; if (pulseIncreasing) { pulseValue++; if (pulseValue >= 35) pulseIncreasing = false; } else { pulseValue--; if (pulseValue <= 0) pulseIncreasing = true; } AnimateTopPlayer(); Invalidate(new Rectangle(0, 0, ClientSize.Width, Math.Min(125, ClientSize.Height))); }
        private void AnimateTopPlayer() { if (dgvLeaderboard.Rows.Count == 0) return; if (dgvLeaderboard.Rows[0].Cells["Player"].Value?.ToString() == "No player statistics available.") return; DataGridViewRow row = dgvLeaderboard.Rows[0]; int pulse = 10 + (int)(9 * (0.5 + 0.5 * Math.Sin(animationPhase * 0.08))); row.DefaultCellStyle.BackColor = Color.FromArgb(27 + pulse, 34 + pulse / 2, 47 + pulse); row.DefaultCellStyle.ForeColor = Color.FromArgb(255, 241, 180); row.DefaultCellStyle.Font = new Font("Segoe UI", 9.5F, FontStyle.Bold); }
        private void EntranceTimer_Tick(object sender, EventArgs e) { if (visibleRows >= dgvLeaderboard.Rows.Count) { entranceTimer.Stop(); for (int i = 0; i < dgvLeaderboard.Rows.Count; i++) { dgvLeaderboard.Rows[i].Visible = true; } return; } visibleRows++; for (int i = 0; i < dgvLeaderboard.Rows.Count; i++) { dgvLeaderboard.Rows[i].Visible = i < visibleRows; } }
        private void StyleButton(Button button, Color color) { button.Size = new Size(170, 40); button.Font = new Font("Segoe UI", 8.5F, FontStyle.Bold); button.ForeColor = Color.White; button.BackColor = color; button.FlatStyle = FlatStyle.Flat; button.FlatAppearance.BorderSize = 1; button.FlatAppearance.BorderColor = Color.FromArgb(70, 155, 220); button.Cursor = Cursors.Hand; }
        private void Button_MouseEnter(object sender, EventArgs e) { Button button = sender as Button; if (button == null) return; button.FlatAppearance.BorderSize = 2; if (button == btnClear) { button.BackColor = Color.FromArgb(215, 65, 78); } else { button.BackColor = Color.FromArgb(45, 115, 190); } }
        private void Button_MouseLeave(object sender, EventArgs e) { Button button = sender as Button; if (button == null) return; button.FlatAppearance.BorderSize = 1; if (button == btnClear) { button.BackColor = dangerColor; } else { button.BackColor = Color.FromArgb(28, 82, 140); } }
        private void Button_MouseDown(object sender, MouseEventArgs e) { Button button = sender as Button; if (button == null) return; if (button == btnClear) { button.BackColor = Color.FromArgb(145, 40, 52); } else { button.BackColor = Color.FromArgb(20, 65, 115); } }
        private void Button_MouseUp(object sender, MouseEventArgs e) { Button button = sender as Button; if (button == null) return; if (button == btnClear) { button.BackColor = Color.FromArgb(215, 65, 78); } else { button.BackColor = Color.FromArgb(45, 115, 190); } }
        private void LeaderboardForm_Load(object sender, EventArgs e) { LoadLeaderboardData(); LoadTournamentLeaderboardData(); StyleTopThree(); StyleTournamentRows(); visibleRows = 0; for (int i = 0; i < dgvLeaderboard.Rows.Count; i++) { dgvLeaderboard.Rows[i].Visible = false; } entranceTimer.Start(); UpdateLayout(); Invalidate(); }
        private void LoadLeaderboardData() { dgvLeaderboard.Rows.Clear(); dgvLeaderboard.Columns.Clear(); dgvLeaderboard.Columns.Add("Rank", "RANK"); dgvLeaderboard.Columns.Add("Player", "PLAYER"); dgvLeaderboard.Columns.Add("Wins", "WINS"); dgvLeaderboard.Columns.Add("Losses", "LOSSES"); dgvLeaderboard.Columns.Add("Draws", "DRAWS"); dgvLeaderboard.Columns.Add("Games", "GAMES"); dgvLeaderboard.Columns.Add("WinRate", "WIN RATE"); List<PlayerStatistics> statistics = FileManager.LoadPlayerStatistics(); List<PlayerStatistics> rankedPlayers = statistics.OrderByDescending(p => p.Wins).ThenByDescending(p => p.WinRate).ThenByDescending(p => p.TotalGames).ToList(); int rank = 1; foreach (PlayerStatistics player in rankedPlayers) { dgvLeaderboard.Rows.Add(rank, player.PlayerName, player.Wins, player.Losses, player.Draws, player.TotalGames, $"{player.WinRate:F1}%"); rank++; } if (dgvLeaderboard.Rows.Count == 0) { dgvLeaderboard.Rows.Add("-", "No player statistics available.", "-", "-", "-", "-", "-"); } lblPlayerCount.Text = "PLAYERS // " + (rankedPlayers.Count).ToString("00"); dgvLeaderboard.Columns["Rank"].FillWeight = 48; dgvLeaderboard.Columns["Player"].FillWeight = 155; dgvLeaderboard.Columns["Wins"].FillWeight = 72; dgvLeaderboard.Columns["Losses"].FillWeight = 72; dgvLeaderboard.Columns["Draws"].FillWeight = 72; dgvLeaderboard.Columns["Games"].FillWeight = 72; dgvLeaderboard.Columns["WinRate"].FillWeight = 92; }
        private void LoadTournamentLeaderboardData() { dgvTournamentLeaderboard.Rows.Clear(); dgvTournamentLeaderboard.Columns.Clear(); dgvTournamentLeaderboard.Columns.Add("Rank", "RANK"); dgvTournamentLeaderboard.Columns.Add("Champion", "CHAMPION"); dgvTournamentLeaderboard.Columns.Add("Wins", "TOURNAMENTS WON"); Dictionary<string, int> championCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); List<string> champions = FileManager.LoadTournamentLeaderboard(); foreach (string champion in champions) { if (!string.IsNullOrWhiteSpace(champion)) { string name = champion.Trim(); if (championCounts.ContainsKey(name)) { championCounts[name]++; } else { championCounts[name] = 1; } } } List<KeyValuePair<string, int>> rankedChampions = championCounts.OrderByDescending(x => x.Value).ThenBy(x => x.Key).ToList(); int rank = 1; foreach (KeyValuePair<string, int> champion in rankedChampions) { dgvTournamentLeaderboard.Rows.Add(rank, champion.Key, champion.Value); rank++; } if (dgvTournamentLeaderboard.Rows.Count == 0) { dgvTournamentLeaderboard.Rows.Add("-", "No tournament champions available.", "-"); } lblChampionCount.Text = "CHAMPIONSHIPS // " + rankedChampions.Sum(x => x.Value).ToString("00"); }
        private void StyleTopThree() { for (int i = 0; i < dgvLeaderboard.Rows.Count; i++) { DataGridViewRow row = dgvLeaderboard.Rows[i]; if (row.Cells["Rank"].Value == null) continue; string rank = row.Cells["Rank"].Value.ToString(); if (rank == "1") { row.DefaultCellStyle.ForeColor = Color.FromArgb(255, 235, 165); row.DefaultCellStyle.Font = new Font("Segoe UI", 9.5F, FontStyle.Bold); } else if (rank == "2") { row.DefaultCellStyle.ForeColor = silverColor; } else if (rank == "3") { row.DefaultCellStyle.ForeColor = bronzeColor; } } }
        private void StyleTournamentRows() { for (int i = 0; i < dgvTournamentLeaderboard.Rows.Count; i++) { DataGridViewRow row = dgvTournamentLeaderboard.Rows[i]; if (row.Cells["Rank"].Value == null) continue; string rank = row.Cells["Rank"].Value.ToString(); if (rank == "1") { row.DefaultCellStyle.ForeColor = Color.FromArgb(255, 220, 145); row.DefaultCellStyle.Font = new Font("Segoe UI", 9.5F, FontStyle.Bold); } else if (rank == "2") { row.DefaultCellStyle.ForeColor = silverColor; } else if (rank == "3") { row.DefaultCellStyle.ForeColor = bronzeColor; } } }
        private void btnClear_Click(object sender, EventArgs e) { DialogResult result = MessageBox.Show("This will permanently remove all player statistics and tournament championship records.\n\nDo you want to continue?", "CLEAR LEADERBOARD", MessageBoxButtons.YesNo, MessageBoxIcon.Warning); if (result != DialogResult.Yes) return; FileManager.SavePlayerStatistics(new List<PlayerStatistics>()); FileManager.SaveTournamentLeaderboard(new List<string>()); LoadLeaderboardData(); LoadTournamentLeaderboardData(); StyleTopThree(); StyleTournamentRows(); visibleRows = 0; for (int i = 0; i < dgvLeaderboard.Rows.Count; i++) { dgvLeaderboard.Rows[i].Visible = false; } entranceTimer.Start(); MessageBox.Show("Player and tournament leaderboards have been cleared successfully.", "DATABASE CLEARED", MessageBoxButtons.OK, MessageBoxIcon.Information); }
        private void btnBack_Click(object sender, EventArgs e) { animationTimer.Stop(); entranceTimer.Stop(); if (returnForm != null) { returnForm.Show(); returnForm.BringToFront(); Close(); return; } MainMenuForm menu = new MainMenuForm(); menu.Show(); Close(); }
